#include<stdio.h>
#include<string.h>
int main() {
    char s[1001]; scanf("%s",s);
    int n=strlen(s), start=0, maxLen=1;
    for(int i=0;i<n;i++){
        // Odd
        int l=i,r=i;
        while(l>=0&&r<n&&s[l]==s[r]){l--;r++;}
        if(r-l-1>maxLen){maxLen=r-l-1;start=l+1;}
        // Even
        l=i;r=i+1;
        while(l>=0&&r<n&&s[l]==s[r]){l--;r++;}
        if(r-l-1>maxLen){maxLen=r-l-1;start=l+1;}
    }
    char res[1001]; strncpy(res,s+start,maxLen); res[maxLen]='\0';
    printf("%s",res);
}

